abel="Chave do novo participante" /><v-text-field v-model="guidedParticipantName" label="Nome do novo participante" /><v-btn size="small" variant="text" :disabled="!guidedParticipantKey || !guidedParticipantName" @click="createAndMapUnknownParticipant(label)">Criar e associar</v-btn></div></div><div v-if="tabularValidation.detailedPreview && tabularValidation.previewRows.length" class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Linha</th><th>Chave</th><th>Valor</th><th>Data</th><th>Método</th></tr></thead><tbody><tr v-for="row in tabularValidation.previewRows" :key="row.rowNumber"><th>{{ row.rowNumber }}</th><td>{{ row.clientItemKey }}</td><td>{{ money(row.amount) }}</td><td>{{ row.occurredOn || '—' }}</td><td>{{ row.attributionMethod || '—' }}</td></tr></tbody></table></div></div>
          <p v-if="!userStore.isAdmin" class="matrix-hint">A confirmação é restrita a ADMIN/OWNER com acesso explícito aos dados sensíveis do fechamento.</p>
        </section>

        <section v-if="showOperations" class="cb-card obligations-card operations-center" aria-labelledby="operations-center-title">
