        </section>

        <section v-if="summary && matrix && selectedClosing.workflowStatus === 'APPROVED'" class="cb-card obligations-card decision-workflow" aria-labelledby="margin-workflow-title">
          <div class="section-heading"><div><p class="eyebrow">Destinação independente</p><h2 id="margin-workflow-title">Margem de Contribuição</h2></div><v-btn variant="tonal" :loading="loadingDecisionData" @click="loadDecisionData">Atualizar decisões</v-btn></div>
          <p class="matrix-hint">Retenção e reserva alocam margem sem pagamento. Compromisso de despesa e distribuição somente emitem obrigações quando a decisão é aprovada.</p>
          <div class="payment-form"><v-text-field v-model="marginPoolKey" label="Pool" /><v-select v-model="marginAllocationType" :items="marginAllocationTypes" label="Destinação" /><v-text-field v-model.number="marginAmount" label="Valor" type="number" min="0.01" /><v-text-field v-model="marginPurpose" label="Finalidade" /><v-text-field v-if="marginNeedsBeneficiary" v-model="marginBeneficiaryName" label="Beneficiário/credor" /><v-text-field v-if="marginAllocationType === 'DISTRIBUTE'" v-model="marginParticipantId" label="ID do participante destinatário" /><v-btn color="primary" :disabled="!canCreateMarginDecision" @click="createMarginDecision">Criar proposta de margem</v-btn></div>
          <div v-for="decision in marginDecisions" :key="decision.id" class="decision-card"><p><strong>{{ decisionStatusLabel(decision.status) }}</strong> · revisão {{ decision.revision }} · alocado {{ money(decision.allocatedAmount) }} · disponível {{ money(decision.unallocatedMargin) }}</p><ul><li v-for="line in decision.allocations" :key="line.id">{{ marginTypeLabel(line.type) }} · {{ money(line.amount) }} · {{ line.purpose }}<template v-if="line.beneficiaryDisplayName"> · {{ line.beneficiaryDisplayName }}</template></li></ul><div class="payment-form"><v-btn v-if="decision.status === 'DRAFT' && userStore.canWrite" @click="submitMarginDecision(decision)">Enviar para revisão</v-btn><v-textarea v-if="decision.status === 'REVIEW' && userStore.isAdmin" v-model="marginApprovalJustification" label="Justificativa da aprovação" /><v-btn v-if="decision.status === 'REVIEW' && userStore.isAdmin" color="success" :disabled="!marginApprovalJustification.trim()" @click="approveMarginDecision(decision)">Aprovar destinação</v-btn></div></div>
        </section>

        <section v-if="summary && matrix" class="cb-card matrix-card">
