          <div v-else class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Domínio</th><th>Principal</th><th>Pago em dinheiro</th><th>Crédito</th><th>Saldo aberto</th><th>Dinheiro</th><th>Resolução</th></tr></thead><tbody><tr v-for="item in filteredObligations" :key="item.id"><th>{{ item.domain === 'PRODUCTIVITY' ? 'Produtividade' : 'Margem' }}</th><td>{{ money(item.principalAmount) }}</td><td>{{ money(item.cashPaidAmount) }}</td><td>{{ money(item.creditedAmount) }}</td><td>{{ money(item.openAmount) }}</td><td><v-chip size="x-small" variant="tonal">{{ statusLabel(item.cashSettlementStatus) }}</v-chip></td><td><v-chip size="x-small" :color="item.resolutionStatus === 'SETTLED' ? 'success' : undefined" variant="tonal">{{ statusLabel(item.resolutionStatus) }}</v-chip></td></tr></tbody></table></div>
          <p class="matrix-hint">Consulta somente. Registrar fatos internos não executa transferência bancária.</p>
        </section>
        <section v-if="summary && matrix && userStore.canWrite" class="cb-card obligations-card manual-payment"><div class="section-heading"><div><p class="eyebrow">Registro interno</p><h2>Pagamento manual</h2></div></div><p class="matrix-hint">Este registro não realiza uma transferência bancária.</p><div class="payment-form"><v-text-field v-model.number="paymentAmount" label="Valor" type="number" min="0.01" /><v-text-field v-model="paymentReference" label="Referência interna" /><v-text-field v-model="paymentExecutedAt" label="Data e hora da ocorrência" type="datetime-local" /><v-btn color="primary" :loading="savingPayment" @click="recordPayment">Registrar como rascunho</v-btn></div><div v-if="recordedPayment"><p class="matrix-hint">Rascunho {{ recordedPayment.id }} · {{ money(recordedPayment.amount) }}</p><v-textarea v-if="userStore.isAdmin" v-model="confirmationJustification" label="Justificativa da confirmação" /><v-text-field v-if="userStore.isAdmin" v-model="confirmationEvidence" label="Evidência (não será exibida depois)" /><div class="payment-form"><v-btn v-if="userStore.isAdmin" color="success" :disabled="!confirmationJustification || !confirmationEvidence" @click="confirmPayment">Confirmar fato interno</v-btn><v-btn color="error" variant="tonal" @click="voidPayment">Anular rascunho</v-btn></div></div></section>
        <section v-if="summary && matrix && (suggestionPaymentId || bankSuggestions)" class="cb-card obligations-card bank-suggestions" aria-labelledby="bank-suggestions-title"><div class="section-heading"><div><p class="eyebrow">Conciliação bancária assistida</p><h2 id="bank-suggestions-title">Sugestões de extrato</h2></div><v-btn v-if="suggestionPaymentId" variant="tonal" :loading="loadingSuggestions" @click="loadBankSuggestions">Atualizar</v-btn></div><p class="matrix-hint">A confirmação ou rejeição registra apenas uma decisão auditável. Não executa operação bancária nem altera saldos, obrigações ou settlement.</p><div v-if="loadingSuggestions" class="cb-empty-state"><v-progress-circular indeterminate size="24" /><p>Buscando candidatos seguros…</p></div><p v-else-if="suggestionError" class="matrix-hint" role="alert">{{ suggestionError }}</p><p v-else-if="bankSuggestions?.classification === 'NO_MATCH'" class="matrix-hint">Nenhum lançamento bancário elegível foi encontrado para esta execução.</p><div v-else-if="bankSuggestions" class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Classificação</th><th>Valor</th><th>Data</th><th>Direção</th><th>Explicação</th><th v-if="userStore.isAdmin">Decisão</th></tr></thead><tbody><tr v-for="candidate in bankSuggestions.candidates" :key="candidate.candidateId"><th><v-chip size="x-small" :color="candidate.classification === 'EXACT' ? 'success' : candidate.classification === 'AMBIGUOUS' ? 'warning' : 'info'" variant="tonal">{{ suggestionLabel(candidate.classification) }}</v-chip></th><td>{{ money(candidate.amount) }}</td><td>{{ formatDate(candidate.transactionDate) }}</td><td>{{ candidate.direction === 'OUTFLOW' ? 'Saída' : 'Entrada' }}</td><td><span class="suggestion-reasons">{{ candidate.reasons.map(reasonLabel).join(' · ') }}</span></td><td v-if="userStore.isAdmin"><div class="reconciliation-actions"><v-btn size="small" color="success" :loading="reconciliationActionId === candidate.candidateId" @click="confirmBankSuggestion(candidate)">Confirmar</v-btn><v-btn size="small" variant="tonal" color="error" @click="rejectionCandidateId = candidate.candidateId">Rejeitar</v-btn></div></td></tr></tbody></table></div><div v-if="userStore.isAdmin && rejectionCandidate" class="payment-form reconciliation-rejection"><v-select v-model="rejectionReason" :items="rejectionReasons" label="Motivo da rejeição" /><v-btn color="error" :loading="reconciliationActionId === rejectionCandidate.candidateId" @click="rejectBankSuggestion">Confirmar rejeição</v-btn><v-btn variant="text" @click="rejectionCandidateId = ''">Cancelar</v-btn></div><div v-if="reconciliationHistory.length" class="reconciliation-history"><p class="eyebrow">Histórico seguro</p><ul><li v-for="item in reconciliationHistory" :key="item.id">{{ item.status === 'CONFIRMED' ? 'Correspondência confirmada' : `Sugestão rejeitada: ${rejectionLabel(item.rejectionReasonCode)}` }} · {{ formatDateTime(item.decidedAt) }}</li></ul></div></section>
        <section v-if="summary && matrix && userStore.canWrite && obligations.length" class="cb-card obligations-card"><div class="section-heading"><div><p class="eyebrow">Fato compensatório</p><h2>Correção financeira</h2></div></div><p class="matrix-hint">A reversão apenas reabre o efeito derivado de uma alocação conciliada. Não executa transferência nem modifica os fatos históricos.</p><div class="payment-form"><v-select v-model="correctionType" :items="correctionTypes" label="Efeito" /><v-select v-model="correctionObligationId" :items="obligations.map(item => ({ title: `${item.domain} · ${money(item.openAmount)}`, value: item.id }))" label="Obrigação de origem" /><v-text-field v-model.number="correctionAmount" label="Valor" type="number" min="0.01" /><template v-if="isSettlementReversal"><v-text-field v-model="reversalAllocationId" label="ID da alocação original" /><v-text-field v-model="reversalTransactionId" label="ID seguro do retorno bancário" /><v-text-field v-model="reversalReasonCode" label="Motivo tipado" /></template><v-btn color="primary" :disabled="!canCreateCorrection" @click="createCorrection">Criar para revisão</v-btn></div><div v-if="correction"><p class="matrix-hint">{{ correction.type }} · {{ correction.status }}<template v-if="correction.rejectionReasonCode"> · {{ correction.rejectionReasonCode }}</template></p><div class="payment-form"><v-btn v-if="correction.status === 'DRAFT'" @click="submitCorrection">Enviar para revisão</v-btn><v-btn v-if="correction.status === 'REVIEW' && userStore.isAdmin" color="success" @click="approveCorrection">Aprovar fato compensatório</v-btn><v-btn v-if="correction.status === 'REVIEW' && userStore.isAdmin" color="error" variant="tonal" @click="rejectCorrection">Rejeitar</v-btn></div></div></section>
        <section v-if="summary && matrix && settlementReversal" class="cb-card obligations-card"><p class="eyebrow">Histórico seguro da reversão</p><p class="matrix-hint">Fato emitido · {{ money(settlementReversal.amount) }} · {{ settlementReversal.reasonCode }} · {{ formatDateTime(settlementReversal.approvedAt) }}</p></section>
        <div v-if="!summary || !matrix" class="cb-empty-state"><v-icon size="40">mdi-calculator-variant-outline</v-icon><p class="cb-empty-state__title">Importe os itens e calcule a apuração</p><p>As fontes tabulares confirmadas invalidam o cálculo anterior até uma nova apuração.</p></div>
      </template>
    </div>

    <v-dialog v-model="drillOpen" max-width="860">
      <v-card><v-card-title>{{ drillTitle }}</v-card-title><v-card-subtitle v-if="drill">Bruto {{ money(drill.grossAmount) }} · Deduções {{ money(drill.deductionAmount) }} · Ajustes {{ signedMoney(drill.adjustmentAmount) }} · Líquido {{ money(drill.netAmount) }}</v-card-subtitle>
        <v-card-text><v-progress-linear v-if="loadingDrill" indeterminate /><div v-else-if="drill" class="drill-list"><article v-for="item in drill.items" :key="item.itemId"><div><strong>{{ item.financialLabel || item.clientItemKey }}</strong><small>{{ item.occurredOn || 'Data não informada' }}</small></div><div><span>{{ money(item.signedGrossAmount) }}</span><span>− {{ money(item.deductionAmount) }}</span><strong>{{ money(item.netAmount) }}</strong></div></article></div></v-card-text>
        <v-card-actions><v-spacer /><v-btn @click="drillOpen = false">Fechar</v-btn></v-card-actions></v-card>
    </v-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import FinancialClosingService, { type AssistedImportProfile, type AssistedImportProfileDetail, type BankReconciliation, type BankReconciliationCandidate, type BankReconciliationSuggestionPage, type CalculationMemory, type CalculationRevision, type ClosingMatrix, type ClosingSource, type ClosingSummary, type DrillDown, type FinancialClosing, type ClosingParticipant, type MatrixRow, type OperationalObligation, type PaymentExecution, type FinancialCorrection, type SettlementReversal, type TabularImportMapping, type TabularImportValidation, type PayoutDecision, type MarginDecision, type ClosingOperations, type TabularImportExecution, type TabularImportIssuePage, type SourceRetention, type ParticipantScore, type ImportReadiness, type ImportReadinessSource, type WorkbookInventory, type WorkbookSheetInventory, type SensitiveWorkspaceGrant } from '@/services/FinancialClosingService'
import { useUserStore } from '@/plugins/userStore'
import WorkspaceService from '@/services/WorkspaceService'
import PageHeader from '@/components/PageHeader.vue'
import AlertStrip from '@/components/AlertStrip.vue'

const userStore = useUserStore()
const closings = ref<FinancialClosing[]>([]); const selectedId = ref(''); const summary = ref<ClosingSummary | null>(null); const matrix = ref<ClosingMatrix | null>(null)
const newClosingMonth = ref(new Date().getMonth() + 1); const newClosingYear = ref(new Date().getFullYear()); const creatingClosing = ref(false); const monthOptions = Array.from({ length: 12 }, (_, index) => ({ title: String(index + 1).padStart(2, '0'), value: index + 1 }))
const sources = ref<ClosingSource[]>([]); const participants = ref<ClosingParticipant[]>([]); const newSourceKey = ref(''); const newSourceName = ref(''); const newParticipantKey = ref(''); const newParticipantName = ref(''); const importSection = ref<HTMLElement | null>(null); const workbookGuide = ref<HTMLElement | null>(null); const workbookFile = ref<File | File[] | null>(null); const workbookInventory = ref<WorkbookInventory | null>(null); const workbookClassifications = ref<Record<string, string>>({}); const workbookSelected = ref<Record<string, boolean>>({}); const inventoryLoading = ref(false); const workbookMessage = ref(''); const guidedSheet = ref<WorkbookSheetInventory | null>(null); const guidedSheetRole = ref<'FINANCIAL_SOURCE' | 'SUPPORT' | 'CONSOLIDATION'>('FINANCIAL_SOURCE'); const guidedMapping = ref({ itemKeyColumn: '', externalReferenceColumn: '', amountColumn: '', occurredOnColumn: '', participantColumn: '' }); const guidedDecimalSeparator = ref<'DOT' | 'COMMA'>('COMMA'); const savingGuidedProfile = ref(false); const guidedSheetRoleOptions = [{ title: 'Fonte financeira que entra no fechamento', value: 'FINANCIAL_SOURCE' }, { title: 'Apoio — não entra no cálculo', value: 'SUPPORT' }, { title: 'Consolidação — somente conferência', value: 'CONSOLIDATION' }]; const decimalSeparatorOptions = [{ title: 'Vírgula (ex.: 1.234,56)', value: 'COMMA' }, { title: 'Ponto (ex.: 1234.56)', value: 'DOT' }]; const manualSetupOpen = ref(false); const importStepOpen = ref(false); const ownerSensitiveAccessEnabled = ref(false)
const retentions = ref<SourceRetention[]>([]); const scores = ref<ParticipantScore[]>([]); const retentionSourceKey = ref(''); const retentionName = ref(''); const retentionPercentage = ref<number | null>(null); const retentionJustification = ref(''); const scoreParticipantId = ref(''); const scoreValue = ref<number | null>(null); const scoreJustification = ref('')
const memory = ref<CalculationMemory | null>(null); const drill = ref<DrillDown | null>(null); const drillOpen = ref(false)
const obligations = ref<OperationalObligation[]>([]); const loadingObligations = ref(false); const obligationDomain = ref('ALL')
const paymentAmount = ref<number | null>(null); const paymentReference = ref(''); const paymentExecutedAt = ref(''); const savingPayment = ref(false); const recordedPayment = ref<PaymentExecution | null>(null); const confirmationJustification = ref(''); const confirmationEvidence = ref('')
const suggestionPaymentId = ref(''); const bankSuggestions = ref<BankReconciliationSuggestionPage | null>(null); const reconciliationHistory = ref<BankReconciliation[]>([]); const loadingSuggestions = ref(false); const suggestionError = ref(''); const reconciliationActionId = ref(''); const rejectionCandidateId = ref(''); const rejectionReason = ref('NOT_SAME_PAYMENT'); const rejectionReasons = [{ title: 'Não é o mesmo pagamento', value: 'NOT_SAME_PAYMENT' }, { title: 'Lançamento bancário duplicado', value: 'DUPLICATE_BANK_ENTRY' }, { title: 'Data incompatível', value: 'DATE_MISMATCH' }, { title: 'Valor incompatível', value: 'AMOUNT_MISMATCH' }, { title: 'Exige revisão manual', value: 'MANUAL_REVIEW_REQUIRED' }]
const correctionType = ref('RELEASE_OPEN_PRINCIPAL'); const correctionObligationId = ref(''); const correctionAmount = ref<number | null>(null); const reversalAllocationId = ref(''); const reversalTransactionId = ref(''); const reversalReasonCode = ref('BANK_RETURN'); const correction = ref<FinancialCorrection | null>(null); const settlementReversal = ref<SettlementReversal | null>(null); const correctionTypes = [{ title: 'Crédito contra principal aberto', value: 'RELEASE_OPEN_PRINCIPAL' }, { title: 'Obrigação complementar', value: 'ISSUE_SUPPLEMENT' }, { title: 'Obrigação de recuperação', value: 'ISSUE_RECOVERY' }, { title: 'Reversão de alocação conciliada', value: 'REVERSE_SETTLEMENT_ALLOCATION' }]
const tabularFile = ref<File | File[] | null>(null); const tabularBatchKey = ref(`TABULAR-${new Date().toISOString().slice(0, 10)}`); const tabularValidating = ref(false); const tabularConfirming = ref(false); const tabularMessage = ref(''); const tabularValidation = ref<TabularImportValidation | null>(null)
const sensitiveAccessConfirmed = ref(false); const enablingSensitiveAccess = ref(false); const eligibleSensitiveAdmins = ref<Array<{ title: string; value: string }>>([]); const selectedSensitiveAdminId = ref(''); const workspaceSensitiveGrants = ref<SensitiveWorkspaceGrant[]>([])
const tabularMapping = ref<TabularImportMapping>({ itemKeyColumn: 'itemKey', sourceIdColumn: 'sourceId', amountColumn: 'amount', occurredOnColumn: 'occurredOn', attributionMethodColumn: 'attributionMethod', participantIdColumn: 'participantId', poolKeyColumn: 'poolKey', defaultAttributionMethod: 'DIRECT_ATTRIBUTION', decimalSeparator: 'DOT' })
const importProfiles = ref<AssistedImportProfile[]>([]); const selectedProfileId = ref(''); const profileKey = ref(''); const profileName = ref(''); const profileSourceKey = ref(''); const profileExpectedSheet = ref(''); const profileItemKeyColumns = ref(''); const profileParticipantExternal = ref(''); const profileParticipantId = ref(''); const profileParticipantMappings = ref<Record<string, string>>({}); const guidedParticipantKey = ref(''); const guidedParticipantName = ref('')
const importReadiness = ref<ImportReadiness | null>(null)
const operations = ref<ClosingOperations | null>(null); const importExecutions = ref<TabularImportExecution[]>([]); const importIssues = ref<TabularImportIssuePage | null>(null); const loadingOperations = ref(false)
const calculationRevisions = ref<CalculationRevision[]>([]); const payoutDecisions = ref<PayoutDecision[]>([]); const marginDecisions = ref<MarginDecision[]>([]); const payoutDecision = ref<PayoutDecision | null>(null); const loadingDecisionData = ref(false); const creatingPayout = ref(false); const payoutDueDate = ref(''); const payoutApprovalJustification = ref(''); const marginApprovalJustification = ref('')
const marginPoolKey = ref('MARGEM_CONTRIBUICAO'); const marginAllocationType = ref('RETAIN'); const marginAmount = ref<number | null>(null); const marginPurpose = ref(''); const marginBeneficiaryName = ref(''); const marginParticipantId = ref(''); const marginAllocationTypes = [{ title: 'Resultado retido', value: 'RETAIN' }, { title: 'Reserva', value: 'RESERVE' }, { title: 'Compromisso de despesa', value: 'EXPENSE_COMMITMENT' }, { title: 'Distribuição', value: 'DISTRIBUTE' }]
const loading = ref(true); const calculating = ref(false); const loadingMemory = ref(false); const loadingDrill = ref(false); const errorMessage = ref(''); const drillTitle = ref('Detalhamento')
const selectedClosing = computed(() => closings.value.find(item => item.id === selectedId.value) || null)
const selectedTabularFile = computed(() => Array.isArray(tabularFile.value) ? tabularFile.value[0] || null : tabularFile.value)
const selectedWorkbookFile = computed(() => Array.isArray(workbookFile.value) ? workbookFile.value[0] || null : workbookFile.value)
const selectedWorkbookSheets = computed(() => workbookInventory.value?.sheets.filter(sheet => workbookSelected.value[sheet.sheetName] && !isPermanentConsolidation(sheet)) || [])
const consolidationWorkbookSheets = computed(() => workbookInventory.value?.sheets.filter(sheet => workbookClassification(sheet) === 'CONSOLIDATION') || [])
const reviewWorkbookSheets = computed(() => workbookInventory.value?.sheets.filter(sheet => !workbookSelected.value[sheet.sheetName] && workbookClassification(sheet) !== 'CONSOLIDATION') || [])
const requiresOwnerSensitiveSetup = computed(() => isOwner.value && !ownerSensitiveAccessEnabled.value)
const showManualSetup = computed(() => manualSetupOpen.value || Boolean(guidedSheet.value))
const showImportStep = computed(() => importStepOpen.value || Boolean(selectedProfileId.value) || Boolean(tabularValidation.value))
const showRuleSetup = computed(() => showImportStep.value && sources.value.length > 0 && participants.value.length > 0)
const showOperations = computed(() => Boolean(operations.value?.pendingActions.length || operations.value?.timeline.length || importExecutions.value.length))
const showCalculateAction = computed(() => Boolean(userStore.canWrite && selectedClosing.value && sources.value.length && importReadiness.value?.readyToCalculate))
const guidedStepLabel = computed(() => {
  if (!workbookInventory.value) return 'Ler abas'
  if (guidedSheet.value) return 'Configurar fonte'
  if (showImportStep.value) return 'Importar fonte'
  return 'Revisar abas'
})
const canConfirmTabularImport = computed(() => Boolean(userStore.isAdmin && selectedClosing.value && selectedTabularFile.value && tabularBatchKey.value.trim() && tabularValidation.value?.valid))
const canSaveRetention = computed(() => Boolean(retentionSourceKey.value && retentionName.value.trim() && retentionPercentage.value !== null && retentionPercentage.value >= 0 && retentionPercentage.value <= 100 && retentionJustification.value.trim()))
const canSaveScore = computed(() => Boolean(scoreParticipantId.value && scoreValue.value !== null && scoreValue.value >= 0 && scoreValue.value <= 85 && scoreJustification.value.trim()))
const isOwner = computed(() => userStore.getTenantRole === 'ROLE_OWNER')
const marginNeedsBeneficiary = computed(() => marginAllocationType.value === 'EXPENSE_COMMITMENT' || marginAllocationType.value === 'DISTRIBUTE')
const canCreateMarginDecision = computed(() => Boolean(userStore.canWrite && marginPoolKey.value.trim() && marginPurpose.value.trim() && marginAmount.value && marginAmount.value > 0 && (!marginNeedsBeneficiary.value || marginBeneficiaryName.value.trim()) && (marginAllocationType.value !== 'DISTRIBUTE' || marginParticipantId.value.trim())))
const closingOptions = computed(() => closings.value.map(item => ({ value: item.id, title: `${String(item.periodMonth).padStart(2, '0')}/${item.periodYear} · ${item.closingKey}` })))
const workflowLabel = computed(() => ({ DRAFT: 'Rascunho', REVIEW: 'Em revisão', APPROVED: 'Aprovado', CANCELLED: 'Cancelado' }[selectedClosing.value?.workflowStatus || 'DRAFT']))
const canCalculate = computed(() => userStore.canWrite && selectedClosing.value?.workflowStatus === 'DRAFT' && selectedClosing.value.currentVersion.versionStatus === 'EDITABLE')
const readinessBlocksCalculation = computed(() => Boolean(importReadiness.value && !importReadiness.value.readyToCalculate))
const unknownParticipantIssues = computed(() => tabularValidation.value?.unmappedParticipantLabels || [])
const guidedHeaders = computed(() => guidedSheet.value?.headers || [])
const optionalGuidedHeaders = computed(() => [{ title: 'Não existe nesta fonte', value: '' }, ...guidedHeaders.value.map(header => ({ title: header, value: header }))])
const guidedMappingWarning = computed(() => {
  const missing = [guidedMapping.value.itemKeyColumn, guidedMapping.value.externalReferenceColumn, guidedMapping.value.amountColumn, guidedMapping.value.occurredOnColumn].some(value => !value)
  if (missing) return 'Escolha identidade, referência externa, valor e data. Sem identidade externa única, não é seguro confirmar a importação.'
  if (guidedMapping.value.itemKeyColumn !== guidedMapping.value.externalReferenceColumn) return 'A identidade e a referência externa serão preservadas como campos distintos. Confirme que ambas identificam o mesmo item de forma estável.'
  return ''
})
const canSaveGuidedProfile = computed(() => Boolean(guidedSheet.value && newSourceKey.value.trim() && newSourceName.value.trim() && !guidedMappingWarning.value))
const headerSummary = computed(() => summary.value ? [{ label: 'Produtividade Líquida', value: money(summary.value.productivityAmount) }, { label: 'Pool não distribuído', value: money(summary.value.undistributedPoolAmount) }, { label: 'Receita líquida', value: money(summary.value.netRevenueAmount) }] : [])
const filteredObligations = computed(() => obligations.value.filter(item => obligationDomain.value === 'ALL' || item.domain === obligationDomain.value))
const rejectionCandidate = computed(() => bankSuggestions.value?.candidates.find(candidate => candidate.candidateId === rejectionCandidateId.value) || null)
const isSettlementReversal = computed(() => correctionType.value === 'REVERSE_SETTLEMENT_ALLOCATION')
const canCreateCorrection = computed(() => Boolean(correctionObligationId.value && correctionAmount.value && (!isSettlementReversal.value || (reversalAllocationId.value && reversalTransactionId.value && reversalReasonCode.value))))
const money = (value: number | undefined) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: selectedClosing.value?.currency || 'BRL' }).format(Number(value || 0))
const signedMoney = (value: number) => `${value > 0 ? '+' : ''}${money(value)}`
const decisionStatusLabel = (status: string) => ({ DRAFT: 'Rascunho', REVIEW: 'Em revisão', APPROVED: 'Aprovada', REJECTED: 'Rejeitada' } as Record<string, string>)[status] || status
const marginTypeLabel = (type: string) => ({ RETAIN: 'Resultado retido', RESERVE: 'Reserva', EXPENSE_COMMITMENT: 'Compromisso de despesa', DISTRIBUTE: 'Distribuição' } as Record<string, string>)[type] || type

async function loadClosings() { loading.value = true; errorMessage.value = ''; try { const { data } = await FinancialClosingService.list(); closings.value = data; if (!selectedId.value && data.length) selectedId.value = data[0].id; if (!data.length || data.some(item => item.id === selectedId.value)) loading.value = false } catch { errorMessage.value = 'Não foi possível carregar as apurações.'; loading.value = false } }
async function loadSetup() { const closing=selectedClosing.value; if(!closing) { sources.value=[]; participants.value=[]; retentions.value=[]; scores.value=[]; eligibleSensitiveAdmins.value=[]; workspaceSensitiveGrants.value=[]; return } try { const [sourceResponse,participantResponse,retentionResponse,scoreResponse]=await Promise.all([FinancialClosingService.sources(closing),FinancialClosingService.participants(closing),FinancialClosingService.sourceRetentions(closing),FinancialClosingService.participantScores(closing)]); sources.value=sourceResponse.data; participants.value=participantResponse.data; retentions.value=retentionResponse.data; scores.value=scoreResponse.data; if(isOwner.value) await Promise.all([loadEligibleSensitiveAdmins(closing.workspaceId),loadWorkspaceSensitiveAccessGrants()]) } catch { sources.value=[]; participants.value=[]; retentions.value=[]; scores.value=[]; eligibleSensitiveAdmins.value=[]; workspaceSensitiveGrants.value=[]; errorMessage.value='Não foi possível carregar a configuração inicial.' } }
async function loadImportProfiles(){const closing=selectedClosing.value;if(!closing)return;try{importProfiles.value=(await FinancialClosingService.importProfiles(closing)).data}catch{importProfiles.value=[]}}
async function loadImportReadiness(){const closing=selectedClosing.value;if(!closing){importReadiness.value=null;return}try{importReadiness.value=(await FinancialClosingService.importReadiness(closing)).data}catch{importReadiness.value=null}}
function selectSourceProfile(profileId:string){ selectedProfileId.value=profileId; void loadSelectedProfile(); goToImport() }
function sourceReadinessLabel(sourceKey:string, status:string){ if(selectedProfileId.value && importProfiles.value.find(profile=>profile.id===selectedProfileId.value)?.sourceKey===sourceKey && tabularValidation.value && !tabularValidation.value.valid)return 'Com pendência crítica'; return ({NOT_CONFIGURED:'Não configurada',READY_TO_IMPORT:'Pronta para importar',IMPORTED:'Importada',CRITICAL_PENDING:'Com pendência crítica'} as Record<string,string>)[status] || status }
function sourceReadinessDetail(source:ImportReadinessSource){ if(sourceReadinessLabel(source.sourceKey,source.status)==='Com pendência crítica')return 'A prévia atual encontrou bloqueios. Resolva-os e valide novamente antes de confirmar.'; return source.detail }
function importIssueTitle(code:string){return ({INVALID_CLIENT_ITEM_KEY:'Identidade única ausente ou ambígua',UNMAPPED_PARTICIPANT:'Participante desconhecido',INVALID_DIRECT_TARGET:'Destino direto inválido',INVALID_AMOUNT_FORMAT:'Valor inválido',MISSING_DATE:'Data obrigatória ausente'} as Record<string,string>)[code] || 'Dados da fonte exigem revisão'}
function importIssueWhy(code:string){return code==='INVALID_CLIENT_ITEM_KEY'?'Sem identidade única, o sistema não consegue garantir que um repasse não será contado duas vezes.':code==='UNMAPPED_PARTICIPANT'?'O responsável da fonte ainda não está associado a um participante canônico desta competência.':'Esta linha não atende ao contrato do perfil e não pode entrar no cálculo com segurança.'}
function importIssueAction(code:string){return code==='INVALID_CLIENT_ITEM_KEY'?'A fonte não fornece identidade única para estes itens. Solicite o identificador externo ou uma regra de deduplicação formal aprovada.':code==='UNMAPPED_PARTICIPANT'?'Mapeie explicitamente o participante para um cadastro existente ou crie-o de forma controlada; depois salve o perfil e valide de novo.':'Corrija a informação na fonte ou ajuste o perfil autorizado e valide novamente.'}
function mapUnknownParticipant(label:string){if(!profileParticipantId.value)return;profileParticipantMappings.value={...profileParticipantMappings.value,[label]:profileParticipantId.value};profileParticipantId.value='';tabularMessage.value='Mapeamento preparado. Salve uma nova versão do perfil e valide o mesmo arquivo novamente.'}
async function createAndMapUnknownParticipant(label:string){ const closing=selectedClosing.value; if(!closing || !guidedParticipantKey.value.trim() || !guidedParticipantName.value.trim()) return; try { const response=await FinancialClosingService.upsertParticipant(closing,guidedParticipantKey.value.trim(),guidedParticipantName.value.trim()); profileParticipantMappings.value={...profileParticipantMappings.value,[label]:response.data.id}; guidedParticipantKey.value=''; guidedParticipantName.value=''; await loadSetup(); tabularMessage.value='Participante criado e mapeamento preparado. Salve uma nova versão do perfil e valide o mesmo arquivo novamente.' } catch { errorMessage.value='Não foi possível criar o participante. Escolha uma chave estável ainda não utilizada.' } }
function applyProfile(detail: AssistedImportProfileDetail){ profileKey.value=detail.profileKey; profileName.value=detail.displayName; profileSourceKey.value=detail.sourceKey; profileExpectedSheet.value=detail.config.expectedSheet || ''; profileItemKeyColumns.value=(detail.config.itemKeyColumns || []).join(' | '); profileParticipantMappings.value={...(detail.config.participantMappings || {})}; tabularMapping.value={...tabularMapping.value,itemKeyColumn:detail.config.itemKeyColumn || '',amountColumn:detail.config.amountColumn,occurredOnColumn:detail.config.occurredOnColumn,externalReferenceColumn:detail.config.externalReferenceColumn || '',participantLabelColumn:detail.config.participantColumn || undefined,defaultAttributionMethod:detail.config.defaultAttributionMethod || 'DIRECT_ATTRIBUTION',defaultPoolKey:detail.config.defaultPoolKey || undefined,decimalSeparator:detail.config.decimalSeparator} }
async function loadSelectedProfile(){const closing=selectedClosing.value;if(!closing||!selectedProfileId.value)return;try{applyProfile((await FinancialClosingService.importProfile(closing,selectedProfileId.value)).data)}catch{errorMessage.value='Não foi possível carregar a configuração protegida do perfil.'}}
function addProfileParticipantMapping(){ const external=profileParticipantExternal.value.trim().replace(/\s+/g, ' ').toUpperCase(); if(!external || !profileParticipantId.value) return; profileParticipantMappings.value={...profileParticipantMappings.value,[external]:profileParticipantId.value}; profileParticipantExternal.value=''; profileParticipantId.value='' }
function removeProfileParticipantMapping(external:string){ const next={...profileParticipantMappings.value}; delete next[external]; profileParticipantMappings.value=next }
async function createImportProfile(){const closing=selectedClosing.value;if(!closing)return;const itemKeyColumns=profileItemKeyColumns.value.split('|').map(value=>value.trim()).filter(Boolean);try{const created=await FinancialClosingService.createImportProfile(closing,{profileKey:profileKey.value,displayName:profileName.value,sourceKey:profileSourceKey.value,config:{format:selectedTabularFile.value?.name.toLowerCase().endsWith('.xlsx')?'XLSX':'CSV',expectedSheet:profileExpectedSheet.value.trim() || undefined,itemKeyColumn:tabularMapping.value.itemKeyColumn,itemKeyColumns:itemKeyColumns.length?itemKeyColumns:undefined,amountColumn:tabularMapping.value.amountColumn,occurredOnColumn:tabularMapping.value.occurredOnColumn,externalReferenceColumn:tabularMapping.value.externalReferenceColumn||tabularMapping.value.itemKeyColumn,participantColumn:tabularMapping.value.participantLabelColumn,participantMappings:profileParticipantMappings.value,positiveDirection:'ADDITION',negativeAsReversal:true,ignoreTotalsAndFormulas:true,defaultAttributionMethod:tabularMapping.value.defaultAttributionMethod||'DIRECT_ATTRIBUTION',defaultPoolKey:tabularMapping.value.defaultPoolKey,decimalSeparator:tabularMapping.value.decimalSeparator}});selectedProfileId.value=created.data.id;await loadImportProfiles();tabularMessage.value='Perfil salvo como nova versão. Valide o arquivo novamente antes de confirmar.'}catch{errorMessage.value='Não foi possível salvar o perfil. Confirme que a fonte está configurada nesta competência.'}}
async function validateProfileImport(){const closing=selectedClosing.value;const file=selectedTabularFile.value;if(!closing||!file||!selectedProfileId.value||!sensitiveAccessConfirmed.value)return;try{const response=await FinancialClosingService.validateProfileImport(closing,file,selectedProfileId.value,true);tabularValidation.value=response.data;tabularMessage.value=response.data.valid?'Arquivo válido para este perfil. Revise os totais antes de confirmar.':'O perfil encontrou exceções. Atualize o mapeamento explícito e valide de novo.'}catch{tabularMessage.value='Não foi possível validar com o perfil. Confira a fonte configurada e a aba esperada.'}}
async function confirmProfileImport(){const closing=selectedClosing.value;const file=selectedTabularFile.value;if(!closing||!file||!selectedProfileId.value||!tabularValidation.value?.valid||!sensitiveAccessConfirmed.value)return;try{const response=await FinancialClosingService.confirmProfileImport(closing,file,tabularBatchKey.value,selectedProfileId.value,true);tabularMessage.value=response.data.replayed?'Este lote já havia sido confirmado; o resultado original foi reutilizado.':'Lote confirmado com o perfil. Recalcule a apuração para atualizar os resultados.';await loadClosings();selectedId.value=closing.id;await Promise.all([loadOperations(),loadImportReadiness()])}catch{errorMessage.value='Não foi possível confirmar o lote com perfil.'}}
async function createClosing() { if(!userStore.isAdmin) return; creatingClosing.value=true; errorMessage.value=''; try { const response=await FinancialClosingService.createOrGet(newClosingMonth.value,newClosingYear.value,'DEFAULT','BRL'); const created=response.data; await loadClosings(); selectedId.value=created.id; await loadSetup(); await loadOperations() } catch { errorMessage.value='Não foi possível iniciar a apuração. Confira a competência e suas permissões.' } finally { creatingClosing.value=false } }
async function addSource() { const closing=selectedClosing.value; if(!closing || !newSourceKey.value.trim() || !newSourceName.value.trim()) return false; try { await FinancialClosingService.upsertSource(closing,newSourceKey.value.trim(),newSourceName.value.trim()); newSourceKey.value=''; newSourceName.value=''; await loadSetup(); return true } catch { errorMessage.value='Não foi possível configurar a fonte.'; return false } }
async function addParticipant() { const closing=selectedClosing.value; if(!closing || !newParticipantKey.value.trim() || !newParticipantName.value.trim()) return; try { await FinancialClosingService.upsertParticipant(closing,newParticipantKey.value.trim(),newParticipantName.value.trim()); newParticipantKey.value=''; newParticipantName.value=''; await loadSetup() } catch { errorMessage.value='Não foi possível configurar o participante.' } }
function participantName(id: string) { return participants.value.find(item => item.id === id)?.displayName || 'Participante' }
async function saveRetention() { const closing=selectedClosing.value; if(!closing || !canSaveRetention.value || retentionPercentage.value === null) return; try { await FinancialClosingService.upsertSourceRetention(closing,{sourceKey:retentionSourceKey.value,displayName:retentionName.value.trim(),percentage:retentionPercentage.value,justification:retentionJustification.value.trim()}); retentionName.value=''; retentionPercentage.value=null; retentionJustification.value=''; await loadSetup(); await loadResult() } catch { errorMessage.value='Não foi possível salvar a retenção. A fonte precisa pertencer ao rascunho atual.' } }
async function deactivateRetention(id: string) { const closing=selectedClosing.value; if(!closing) return; const justification=window.prompt('Informe a justificativa para desativar a retenção.'); if(!justification?.trim()) return; try { await FinancialClosingService.deactivateSourceRetention(closing,id,justification.trim()); await loadSetup(); await loadResult() } catch { errorMessage.value='Não foi possível desativar a retenção.' } }
async function saveScore() { const closing=selectedClosing.value; if(!closing || !canSaveScore.value || scoreValue.value === null) return; try { await FinancialClosingService.upsertParticipantScore(closing,{participantId:scoreParticipantId.value,score:scoreValue.value,justification:scoreJustification.value.trim()}); scoreValue.value=null; scoreJustification.value=''; await loadSetup(); await loadResult() } catch { errorMessage.value='A pontuação deve estar entre 0% e 85%.' } }
async function enableOwnSensitiveAccess() { const closing=selectedClosing.value; const userId=userStore.getUser.id; if(!closing || !userId || !sensitiveAccessConfirmed.value) return; enablingSensitiveAccess.value=true; try { await FinancialClosingService.grantSensitiveAccess(closing,userId,true); ownerSensitiveAccessEnabled.value=true; workbookMessage.value='Leitura protegida habilitada para este fechamento. Agora escolha a planilha e leia as abas.' } catch { errorMessage.value='Não foi possível habilitar o acesso sensível. Confirme que você é OWNER deste workspace.' } finally { enablingSensitiveAccess.value=false } }
async function loadEligibleSensitiveAdmins(workspaceId: string) { try { const { data } = await WorkspaceService.listMembers(workspaceId); eligibleSensitiveAdmins.value=(Array.isArray(data)?data:[]).filter((member:any)=>member?.role==='ROLE_ADMIN'&&member?.id).map((member:any)=>({value:member.id,title:member.username||member.email||'ADMIN'})) } catch { eligibleSensitiveAdmins.value=[] } }
async function loadWorkspaceSensitiveAccessGrants() { try { workspaceSensitiveGrants.value=(await FinancialClosingService.workspaceSensitiveAccessGrants()).data } catch { workspaceSensitiveGrants.value=[] } }
function sensitiveAdminName(userId: string) { return eligibleSensitiveAdmins.value.find(item => item.value === userId)?.title || 'ADMIN autorizado' }
async function grantWorkspaceSensitiveAccess() { if(!selectedSensitiveAdminId.value) return; enablingSensitiveAccess.value=true; try { await FinancialClosingService.grantWorkspaceSensitiveAccess(selectedSensitiveAdminId.value); await loadWorkspaceSensitiveAccessGrants(); tabularMessage.value='O acesso sensível permanente foi concedido para este workspace e registrado em auditoria.'; selectedSensitiveAdminId.value='' } catch { errorMessage.value='Não foi possível conceder o acesso sensível permanente ao ADMIN selecionado.' } finally { enablingSensitiveAccess.value=false } }
async function revokeWorkspaceSensitiveAccess(userId: string) { enablingSensitiveAccess.value=true; try { await FinancialClosingService.revokeWorkspaceSensitiveAccess(userId); await loadWorkspaceSensitiveAccessGrants(); tabularMessage.value='O acesso sensível permanente foi revogado imediatamente e registrado em auditoria.' } catch { errorMessage.value='Não foi possível revogar o acesso sensível permanente.' } finally { enablingSensitiveAccess.value=false } }
function goToImport() { importStepOpen.value=true; if (typeof importSection.value?.scrollIntoView === 'function') importSection.value.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
function goToWorkbookGuide() { if (typeof workbookGuide.value?.scrollIntoView === 'function') workbookGuide.value.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
function workbookSheetLabel(classification:string) { return ({ FINANCIAL_SOURCE_PROBABLE:'Fonte financeira provável', CONSOLIDATION:'Consolidação', SUPPORT_REVIEW:'Apoio / decisão necessária' } as Record<string,string>)[classification] || classification }
function isPermanentConsolidation(sheet: WorkbookSheetInventory) { const name=sheet.sheetName.trim().toUpperCase(); return name==='GERAL'||name==='FECHAMENTO' }
function workbookClassification(sheet: WorkbookSheetInventory) { return isPermanentConsolidation(sheet) ? 'CONSOLIDATION' : workbookClassifications.value[sheet.sheetName] || sheet.classification }
async function inventoryWorkbook() { const closing=selectedClosing.value; const file=selectedWorkbookFile.value; if(!closing || !file || !sensitiveAccessConfirmed.value) return; inventoryLoading.value=true; workbookMessage.value=''; try { workbookInventory.value=(await FinancialClosingService.workbookInventory(closing,file,true)).data; workbookClassifications.value=Object.fromEntries(workbookInventory.value.sheets.map(sheet=>[sheet.sheetName,sheet.classification])); workbookSelected.value=Object.fromEntries(workbookInventory.value.sheets.map(sheet=>[sheet.sheetName,sheet.selectionStatus==='AUTO_SELECTED'])); workbookMessage.value='Inventário concluído. Fontes conhecidas foram preparadas; revise apenas exceções e mudanças.' } catch (error:any) { workbookInventory.value=null; workbookMessage.value=error?.response?.status===403?'Habilite o acesso protegido antes de ler a planilha.':'Não foi possível ler o workbook. Use um XLSX de até 5 MiB.' } finally { inventoryLoading.value=false } }
function removeWorkbookSelection(sheet: WorkbookSheetInventory) { workbookSelected.value={...workbookSelected.value,[sheet.sheetName]:false}; workbookMessage.value=`${sheet.sheetName} foi removida da preparação. Nenhuma importação foi realizada.` }
function prepareWorkbookSource(sheet:WorkbookSheetInventory) {
  const existing=sources.value.find(source=>source.sourceKey===sheet.suggestedSourceKey)
  if(existing && sheet.recommendedProfileId){ selectedProfileId.value=sheet.recommendedProfileId; guidedSheet.value=null; void loadSelectedProfile(); workbookMessage.value='Perfil selecionado. Envie agora um arquivo contendo somente esta aba para validar e confirmar.'; goToImport(); return }
  guidedSheet.value=sheet; guidedSheetRole.value='FINANCIAL_SOURCE'; newSourceKey.value=sheet.suggestedSourceKey; newSourceName.value=sheet.sheetName
  const suggested=sheet.mappingSuggestion
  guidedMapping.value={itemKeyColumn:suggested?.itemKeyColumn || suggested?.externalReferenceColumn || '', externalReferenceColumn:suggested?.externalReferenceColumn || suggested?.itemKeyColumn || '', amountColumn:suggested?.amountColumn || '', occurredOnColumn:suggested?.occurredOnColumn || '', participantColumn:suggested?.participantColumn || ''}
  if(sheet.recommendedProfileId){ selectedProfileId.value=sheet.recommendedProfileId; void loadSelectedProfile() }
}
function excludeGuidedSheet(){ const sheet=guidedSheet.value; if(!sheet)return; workbookClassifications.value={...workbookClassifications.value,[sheet.sheetName]:guidedSheetRole.value}; workbookMessage.value=`${sheet.sheetName} foi marcada como ${guidedSheetRole.value === 'CONSOLIDATION' ? 'consolidação' : 'apoio'} apenas nesta leitura. Nenhuma fonte ou item foi criado.`; guidedSheet.value=null }
async function saveGuidedSourceProfile() {
  const closing=selectedClosing.value; const sheet=guidedSheet.value
  if(!closing || !sheet || !canSaveGuidedProfile.value) return
  savingGuidedProfile.value=true
  try {
    const sourceKey=newSourceKey.value.trim(); const displayName=newSourceName.value.trim()
    await FinancialClosingService.upsertSource(closing,sourceKey,displayName)
    const profile=await FinancialClosingService.createImportProfile(closing,{profileKey:`${sourceKey}_TABULAR`,displayName:`${displayName} · perfil tabular`,sourceKey,config:{format:'XLSX',expectedSheet:sheet.sheetName,itemKeyColumn:guidedMapping.value.itemKeyColumn,amountColumn:guidedMapping.value.amountColumn,occurredOnColumn:guidedMapping.value.occurredOnColumn,externalReferenceColumn:guidedMapping.value.externalReferenceColumn,participantColumn:guidedMapping.value.participantColumn || undefined,participantMappings:{},positiveDirection:'ADDITION',negativeAsReversal:true,ignoreTotalsAndFormulas:true,defaultAttributionMethod:'DIRECT_ATTRIBUTION',decimalSeparator:guidedDecimalSeparator.value,headerSignature:sheet.headers || []}})
    selectedProfileId.value=profile.data.id; workbookSelected.value={...workbookSelected.value,[sheet.sheetName]:true}; guidedSheet.value=null; importStepOpen.value=true
    await Promise.all([loadSetup(),loadImportProfiles(),loadImportReadiness()]); await loadSelectedProfile()
    workbookMessage.value='Fonte e perfil salvos para recorrência. Agora envie uma cópia desta única aba para validar. Se aparecer participante desconhecido, associe-o explicitamente antes de confirmar.'
    goToImport()
  } catch { errorMessage.value='Não foi possível salvar a fonte e o perfil. Confirme a chave da fonte e os campos homologados.' } finally { savingGuidedProfile.value=false }
}
async function loadResult() { const closing = selectedClosing.value; if (!closing) return; loading.value = true; memory.value = null; errorMessage.value = ''; try { const [summaryResponse, matrixResponse] = await Promise.all([FinancialClosingService.summary(closing), FinancialClosingService.matrix(closing)]); summary.value = summaryResponse.data; matrix.value = matrixResponse.data } catch (error: any) { summary.value = null; matrix.value = null; errorMessage.value = error?.response?.status === 409 ? 'Os dados mudaram e o cálculo precisa ser refeito.' : 'Não foi possível carregar o resultado da apuração.' } finally { loading.value = false } }
async function loadObligations() { loadingObligations.value = true; try { obligations.value = (await FinancialClosingService.obligations()).data } catch { obligations.value = [] } finally { loadingObligations.value = false } }
async function loadOperations() { const closing=selectedClosing.value; if(!closing)return; loadingOperations.value=true; importIssues.value=null; try { const [operationsResponse,importsResponse]=await Promise.all([FinancialClosingService.operations(closing),FinancialClosingService.tabularImportExecutions(closing)]); operations.value=operationsResponse.data; importExecutions.value=importsResponse.data.items } catch { operations.value=null; importExecutions.value=[]; errorMessage.value='Não foi possível carregar a central operacional.' } finally { loadingOperations.value=false } }
async function loadImportIssues(id:string) { const closing=selectedClosing.value; if(!closing)return; try { importIssues.value=(await FinancialClosingService.tabularImportIssues(closing,id)).data } catch { errorMessage.value='Não foi possível consultar os erros seguros da importação.' } }
async function validateTabularImport() { const closing = selectedClosing.value; const file = selectedTabularFile.value; if (!closing || !file || !userStore.isAdmin || !sensitiveAccessConfirmed.value) return; tabularValidating.value = true; tabularMessage.value = ''; try { const response = await FinancialClosingService.validateTabularImport(closing, file, tabularMapping.value, true); tabularValidation.value = response.data; tabularMessage.value = response.data.valid ? 'Arquivo válido. Revise os totais antes de confirmar o lote.' : 'O arquivo possui erros e não pode ser confirmado.' } catch (error: any) { tabularValidation.value = error?.response?.data?.issues ? error.response.data : null; tabularMessage.value = 'Não foi possível validar a planilha. Confira o arquivo e o mapeamento.' } finally { tabularValidating.value = false } }
async function confirmTabularImport() { const closing = selectedClosing.value; const file = selectedTabularFile.value; if (!closing || !file || !tabularValidation.value?.valid || !sensitiveAccessConfirmed.value) return; tabularConfirming.value = true; tabularMessage.value = ''; try { const response = await FinancialClosingService.confirmTabularImport(closing, file, tabularBatchKey.value.trim(), tabularMapping.value, true); tabularMessage.value = response.data.replayed ? 'Este lote já havia sido confirmado; o resultado original foi reutilizado.' : 'Lote normalizado confirmado. Recalcule a apuração para atualizar os resultados.'; await loadClosings(); selectedId.value = closing.id; summary.value = null; matrix.value = null } catch (error: any) { if (error?.response?.data?.issues) { tabularValidation.value = error.response.data; tabularMessage.value = 'A confirmação foi bloqueada pelos erros de validação.' } else tabularMessage.value = error?.response?.status === 403 ? 'A confirmação exige ADMIN/OWNER com concessão explícita aos dados sensíveis.' : 'Não foi possível confirmar o lote.' } finally { tabularConfirming.value = false } }
async function loadDecisionData() { const closing = selectedClosing.value; if (!closing) return; loadingDecisionData.value = true; try { const [revisions, payouts, margins] = await Promise.all([FinancialClosingService.calculationRevisions(closing), FinancialClosingService.payoutDecisions(closing), FinancialClosingService.marginDecisions(closing)]); calculationRevisions.value = revisions.data; payoutDecisions.value = payouts.data; marginDecisions.value = margins.data; payoutDecision.value = payouts.data.find(item => item.status !== 'APPROVED') || payouts.data[0] || null } catch { errorMessage.value = 'Não foi possível carregar as revisões e decisões.' } finally { loadingDecisionData.value = false } }
async function createPayoutDecision() { const closing = selectedClosing.value; if (!closing) return; creatingPayout.value = true; try { payoutDecision.value = (await FinancialClosingService.createPayoutDecision(closing, payoutDueDate.value || undefined)).data; await loadDecisionData() } catch { errorMessage.value = 'Não foi possível criar a proposta de repasse. Confirme que o cálculo atual está conciliado.' } finally { creatingPayout.value = false } }
async function submitPayoutDecision() { const closing = selectedClosing.value; if (!closing || !payoutDecision.value) return; try { payoutDecision.value = (await FinancialClosingService.submitPayoutDecision(closing, payoutDecision.value.id, payoutDecision.value.revision)).data; await loadClosings(); selectedId.value = closing.id } catch { errorMessage.value = 'Não foi possível enviar a proposta para revisão.' } }
async function approvePayoutDecision() { const closing = selectedClosing.value; if (!closing || !payoutDecision.value) return; try { payoutDecision.value = (await FinancialClosingService.approvePayoutDecision(closing, payoutDecision.value.id, payoutDecision.value.revision, payoutApprovalJustification.value)).data; await Promise.all([loadClosings(), loadObligations(), loadDecisionData()]); selectedId.value = closing.id } catch { errorMessage.value = 'Não foi possível aprovar a proposta. A aprovação exige um aprovador elegível e conciliação integral.' } }
async function createMarginDecision() { const closing = selectedClosing.value; if (!closing || !canCreateMarginDecision.value || !marginAmount.value) return; const type = marginAllocationType.value; const beneficiary = type === 'EXPENSE_COMMITMENT' ? { type: 'EXTERNAL_CREDITOR', displayName: marginBeneficiaryName.value.trim(), externalReference: `ui:${marginBeneficiaryName.value.trim()}` } : undefined; const beneficiaries = type === 'DISTRIBUTE' ? [{ clientBeneficiaryKey: marginParticipantId.value.trim(), amount: marginAmount.value, beneficiary: { type: 'CLOSING_PARTICIPANT', closingParticipantId: marginParticipantId.value.trim(), displayName: marginBeneficiaryName.value.trim() } }] : undefined; try { await FinancialClosingService.createMarginDecision(closing, { poolKey: marginPoolKey.value.trim(), allocations: [{ type, amount: marginAmount.value, purpose: marginPurpose.value.trim(), beneficiary, beneficiaries }] }); await loadDecisionData() } catch { errorMessage.value = 'Não foi possível criar a proposta de margem. Revise a capacidade do pool e o beneficiário.' } }
async function submitMarginDecision(decision: MarginDecision) { const closing = selectedClosing.value; if (!closing) return; try { await FinancialClosingService.submitMarginDecision(closing, decision.id, decision.revision); await loadDecisionData() } catch { errorMessage.value = 'Não foi possível enviar a destinação de margem para revisão.' } }
async function approveMarginDecision(decision: MarginDecision) { const closing = selectedClosing.value; if (!closing) return; try { await FinancialClosingService.approveMarginDecision(closing, decision.id, decision.revision, marginApprovalJustification.value); await Promise.all([loadDecisionData(), loadObligations()]) } catch { errorMessage.value = 'Não foi possível aprovar a destinação de margem.' } }
async function recordPayment() { if (!paymentAmount.value || paymentAmount.value <= 0) return; savingPayment.value = true; try { recordedPayment.value = (await FinancialClosingService.recordPayment({ direction: 'OUTBOUND', currency: selectedClosing.value?.currency || 'BRL', amount: paymentAmount.value, externalReference: paymentReference.value || undefined, idempotencyKey: crypto.randomUUID(), executedAt: paymentExecutedAt.value ? new Date(paymentExecutedAt.value).toISOString() : undefined })).data } catch { errorMessage.value = 'Não foi possível registrar o rascunho.' } finally { savingPayment.value = false } }
async function confirmPayment() { if (!recordedPayment.value) return; try { const paymentId = recordedPayment.value.id; await FinancialClosingService.confirmPayment(paymentId, { justification: confirmationJustification.value, evidenceReference: confirmationEvidence.value, idempotencyKey: crypto.randomUUID() }); recordedPayment.value = null; confirmationEvidence.value = ''; confirmationJustification.value = ''; suggestionPaymentId.value = paymentId; await Promise.all([loadObligations(), loadBankSuggestions()]) } catch { errorMessage.value = 'Não foi possível confirmar o fato interno.' } }
async function voidPayment() { if (!recordedPayment.value) return; try { await FinancialClosingService.voidPayment(recordedPayment.value.id, 'Anulado pelo operador antes da confirmação'); recordedPayment.value = null } catch { errorMessage.value = 'Não foi possível anular o rascunho.' } }
async function loadBankSuggestions() { if (!suggestionPaymentId.value) return; loadingSuggestions.value = true; suggestionError.value = ''; try { const [suggestions, history] = await Promise.all([FinancialClosingService.bankReconciliationSuggestions(suggestionPaymentId.value), FinancialClosingService.bankReconciliationHistory(suggestionPaymentId.value)]); bankSuggestions.value = suggestions.data; reconciliationHistory.value = history.data } catch { bankSuggestions.value = null; reconciliationHistory.value = []; suggestionError.value = 'Não foi possível consultar as sugestões bancárias.' } finally { loadingSuggestions.value = false } }
async function confirmBankSuggestion(candidate: BankReconciliationCandidate) { if (!suggestionPaymentId.value) return; reconciliationActionId.value = candidate.candidateId; suggestionError.value = ''; try { await FinancialClosingService.confirmBankReconciliation(suggestionPaymentId.value, { financialTransactionId: candidate.candidateId, expectedCandidateFingerprint: candidate.candidateFingerprint }, crypto.randomUUID()); await loadBankSuggestions() } catch (error: any) { suggestionError.value = error?.response?.status === 409 ? 'A sugestão ficou obsoleta ou já recebeu uma decisão. Atualize a consulta.' : 'Não foi possível confirmar a correspondência.' } finally { reconciliationActionId.value = '' } }
async function rejectBankSuggestion() { const candidate = rejectionCandidate.value; if (!candidate || !suggestionPaymentId.value) return; reconciliationActionId.value = candidate.candidateId; suggestionError.value = ''; try { await FinancialClosingService.rejectBankReconciliation(suggestionPaymentId.value, { financialTransactionId: candidate.candidateId, expectedCandidateFingerprint: candidate.candidateFingerprint, reasonCode: rejectionReason.value }, crypto.randomUUID()); rejectionCandidateId.value = ''; await loadBankSuggestions() } catch (error: any) { suggestionError.value = error?.response?.status === 409 ? 'A sugestão ficou obsoleta ou já recebeu uma decisão. Atualize a consulta.' : 'Não foi possível rejeitar a sugestão.' } finally { reconciliationActionId.value = '' } }
async function createCorrection() { if (!canCreateCorrection.value || !correctionAmount.value) return; try { correction.value = (await FinancialClosingService.createCorrection({ type: correctionType.value, originalObligationId: correctionObligationId.value, amount: correctionAmount.value, ...(isSettlementReversal.value ? { originalAllocationId: reversalAllocationId.value, reversalFinancialTransactionId: reversalTransactionId.value, reasonCode: reversalReasonCode.value } : {}) })).data } catch { errorMessage.value = 'Não foi possível criar a correção.' } }
async function submitCorrection() { if (!correction.value) return; try { correction.value = (await FinancialClosingService.submitCorrection(correction.value.id, correction.value.revision)).data } catch { errorMessage.value = 'Não foi possível enviar a correção.' } }
async function approveCorrection() { if (!correction.value) return; try { correction.value = (await FinancialClosingService.approveCorrection(correction.value.id, correction.value.revision)).data; if (correction.value.type === 'REVERSE_SETTLEMENT_ALLOCATION') settlementReversal.value = (await FinancialClosingService.settlementReversal(correction.value.id)).data; await loadObligations() } catch { errorMessage.value = 'Não foi possível aprovar a correção.' } }
async function rejectCorrection() { if (!correction.value) return; try { correction.value = (await FinancialClosingService.rejectCorrection(correction.value.id, correction.value.revision, 'RETURN_NOT_ACCEPTED')).data } catch { errorMessage.value = 'Não foi possível rejeitar a correção.' } }
async function calculate() { const closing = selectedClosing.value; if (!closing || readinessBlocksCalculation.value) { errorMessage.value='Importe todas as fontes configuradas por perfil antes de calcular.'; return } calculating.value = true; try { await FinancialClosingService.calculate(closing); await loadClosings(); selectedId.value = closing.id; await Promise.all([loadResult(), loadOperations()]) } catch { errorMessage.value = 'Não foi possível recalcular a apuração. Revise as fontes pendentes.' } finally { calculating.value = false } }
async function toggleMemory() { if (memory.value) { memory.value = null; return } const closing = selectedClosing.value; if (!closing) return; loadingMemory.value = true; try { memory.value = (await FinancialClosingService.memory(closing)).data } finally { loadingMemory.value = false } }
async function openDrillDown(row: MatrixRow, source: ClosingSource) { const closing = selectedClosing.value; if (!closing) return; drillTitle.value = `${row.participant.displayName} · ${source.displayName}`; drillOpen.value = true; loadingDrill.value = true; drill.value = null; try { drill.value = (await FinancialClosingService.drillDown(closing, row.participant.id, source.id)).data } finally { loadingDrill.value = false } }
function prettyMemory(raw: string) { try { return JSON.stringify(JSON.parse(raw), null, 2) } catch { return raw } }
function statusLabel(status: string) { return ({ OPEN: 'Aberto', PARTIAL: 'Parcial', PAID: 'Pago em dinheiro', SETTLED: 'Resolvido por crédito', NOT_APPLICABLE: 'Não aplicável' } as Record<string,string>)[status] || status }
function suggestionLabel(status: string) { return ({ EXACT: 'Correspondência exata', LIKELY: 'Correspondência provável', AMBIGUOUS: 'Revisão manual', NO_MATCH: 'Sem correspondência' } as Record<string,string>)[status] || status }
function reasonLabel(reason: string) { return ({ WORKSPACE_MATCH: 'mesmo espaço', DIRECTION_MATCH: 'direção compatível', AMOUNT_EXACT: 'valor exato', DATE_WINDOW_MATCH: 'data próxima', REFERENCE_HMAC_MATCH: 'referência compatível', UNLINKED_IN_V19_A: 'sem vínculo prévio' } as Record<string,string>)[reason] || reason }
function formatDate(value: string) { return new Intl.DateTimeFormat('pt-BR').format(new Date(`${value}T12:00:00`)) }
function formatDateTime(value: string) { return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) }
function rejectionLabel(reason?: string | null) { return ({ NOT_SAME_PAYMENT: 'não é o mesmo pagamento', DUPLICATE_BANK_ENTRY: 'lançamento duplicado', DATE_MISMATCH: 'data incompatível', AMOUNT_MISMATCH: 'valor incompatível', MANUAL_REVIEW_REQUIRED: 'revisão manual' } as Record<string, string>)[reason || ''] || 'motivo registrado' }
watch(selectedId, () => { loadResult(); loadOperations(); loadSetup(); loadImportProfiles(); loadImportReadiness() }); onMounted(async () => { await loadClosings(); await Promise.all([loadObligations(),loadOperations(),loadSetup(),loadImportProfiles(),loadImportReadiness()]) })
</script>

