v{display:flex;justify-content:space-between;gap:12px}.reconciliation-card dt{color:var(--cb-text-muted,#667085)}.reconciliation-card dd{font-weight:700;margin:0}.reconciliation-card>p,.memory-card>p{color:var(--cb-text-muted,#667085);font-size:.88rem}.memory-list{max-height:300px;overflow:auto}.memory-list details{border-top:1px solid #e7e9ef;padding:10px 0}.memory-list pre{white-space:pre-wrap;font-size:.72rem;background:#f7f8fb;padding:10px}.residual{display:flex;justify-content:space-between;border-top:1px solid #e7e9ef;margin-top:16px;padding-top:16px}.drill-list article{display:flex;justify-content:space-between;gap:18px;padding:14px 0;border-bottom:1px solid #e7e9ef}.drill-list article>div{display:flex;gap:16px}.drill-list article>div:first-child{flex-direction:column;gap:2px}.drill-list small{color:var(--cb-text-muted,#667085)}.payment-form,.reconciliation-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:12px}.payment-form :deep(.v-input){min-width:190px;flex:1}.reconciliation-history{margin-top:18px;border-top:1px solid #e7e9ef;padding-top:14px}.reconciliation-history ul{margin:8px 0 0;padding-left:18px;color:var(--cb-text-muted,#667085)}.tabular-import{margin:18px 0}.tabular-mapping{margin-top:14px;padding:12px;background:#f7f8fb;border-radius:8px}.tabular-mapping summary{cursor:pointer;font-weight:600}.tabular-result{margin-top:14px;border-top:1px solid #e7e9ef;padding-top:12px}.tabular-issues{margin:10px 0 0;padding-left:20px;color:var(--cb-negative,#b42318);font-size:.86rem}.operations-center{margin:18px 0}.operations-center h3{font-size:1rem;margin:20px 0 8px}.pending-actions{padding:12px;border-left:4px solid var(--cb-primary,#3451b2);background:#f7f8fb}.pending-actions ul{margin:6px 0 0;padding-left:20px}.pending-actions small,.operations-timeline small{color:var(--cb-text-muted,#667085)}.operations-timeline{margin:8px 0 0;padding-left:22px}.operations-timeline li{padding:8px 0;display:grid;gap:2px;border-bottom:1px solid #e7e9ef}.operations-timeline span{font-size:.9rem}
